// Narration timing (generated by audio/align.py) — the single source of truth for picture and sound sync.
import tl from '../../build/timeline.json';
export interface Word { w: string; start: number; end: number }
export interface Beat { id: string; scene: string; text: string; start: number; end: number; words: Word[] }
export const TL = tl as { fps: number; width: number; height: number; duration: number; preroll: number; beats: Beat[] };
export const FPS = TL.fps;
export const DURATION = TL.duration;
const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9-]/g, '');
export function B(id: string): Beat { const b = TL.beats.find((x) => x.id === id); if (!b) throw new Error('beat ' + id); return b; }
/** Start time of a word inside a beat (nth occurrence). */
export function Wd(id: string, w: string, nth = 0): Word {
  const ws = B(id).words.filter((x) => norm(x.w) === norm(w));
  if (!ws[nth]) throw new Error(`word ${w} in ${id}`);
  return ws[nth];
}
export const ws = (id: string, w: string, nth = 0) => Wd(id, w, nth).start;
export const we = (id: string, w: string, nth = 0) => Wd(id, w, nth).end;
